    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find leftmost index to replace
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

