def solve(tokens):
    """Evaluate Reverse Polish Notation expression with integer division truncating toward zero.
    Uses integer arithmetic to avoid floating point issues.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Truncate toward zero using integer ops
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Compute absolute division then apply sign
                quotient = abs(a) // abs(b)
                res = quotient if (a * b) >= 0 else -quotient
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

