def solve(s):
    """Return True if brackets in s are balanced.
    Accepts a string or any iterable of characters.
    """
    # Convert to iterable of characters
    if isinstance(s, str):
        seq = s
    else:
        try:
            seq = list(s)
        except Exception:
            seq = [s]
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in seq:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

