def solve(nums):
    # Ensure we work on a list copy
    if not isinstance(nums, (list, tuple)):
        try:
            nums = list(nums)
        except Exception:
            return []
    a = list(nums)
    n = len(a)
    # Find the first index i from the end where a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i == -1:
        # Last permutation, return sorted
        return sorted(a)
    # Find smallest element greater than a[i] to the right
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap
    a[i], a[j] = a[j], a[i]
    # Reverse suffix
    a[i+1:] = reversed(a[i+1:])
    return a

